p_chk_c:		; call chk
			movea.l (sp)+, a0		; got
			move.w (a0), var_chk_got
			movea.l (sp)+, a0		; want
			move.w (a0), var_chk_want
			move.l sp, p_chk_rs
			lea p_chk, sp
