; ============================================================

			even
;## ntc_data @shared
; ------------------------------------------------------------
; The core every program has: the thread / real stack switch
; ------------------------------------------------------------
; (NTC_RS / NTC_TS, the macros that switch to the real stack and back, are written
; by the compiler at the top of the program, before anything uses them)
ntc_next:	rts						; A6 target that continues the thread

			even
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jsr ntc_plat_exit
ntc_stop_loop:
			bra ntc_stop_loop		; a Mega Drive has nowhere to go back to

			even
;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			NTC_RS
			jsr ntc_plat_getkey
			NTC_TS
			rts

			even
;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			bne kw_gif_go
			addq.l #4, sp
			rts
kw_gif_go:
			movea.l (sp), sp
			rts

			even
;## kw_goto_iftrue
;kw_goto_iftrue, <label>  - branch if Z (true)
kw_goto_iftrue:
			beq kw_git_go
			addq.l #4, sp
			rts
kw_git_go:
			movea.l (sp), sp
			rts

			even
;## ntc_for_jump
; tails for the FOR / NEXT keywords: SP = thread at the label long
ntc_for_take:
			movea.l (sp), sp
			rts
ntc_for_skip:
			addq.l #4, sp
			rts

			even
;## kw_next1l ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit (past 32767: ends)
kw_next1l:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			addq.w #1, (a0)
			bvs ntc_for_skip
			cmp.w (a0), d1
			bge ntc_for_take		; limit >= var
			addq.l #4, sp
			rts

			even
;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			move.l (sp)+, d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), (a1)
			rts

			even
;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_ftov
;kw_ftov, <destvar>  - Z flag to var: true = -1, false = 0
kw_ftov:
			seq d0
			ext.w d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

; ============================================================
; Arithmetic (16 bit, wrapping)
; ============================================================

			even
;## kw_inc
kw_inc:
			movea.l (sp)+, a0
			addq.w #1, (a0)
			rts

			even
;## kw_dec
kw_dec:
			movea.l (sp)+, a0
			subq.w #1, (a0)
			rts

			even
;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			add.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_4x
kw_4x:
			movea.l (sp)+, a0
			move.w (a0), d0
			add.w d0, d0
			add.w d0, d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_mulvv
;kw_mulvv, <var1>, <var2>, <destvar>  - low 16 bits
kw_mulvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			muls.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_mulvl
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			muls.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_cmp
; tails: d0 = a, d1 = b, test a <rel> b
ntc_cmp_slt:
			cmp.w d1, d0
			slt d0
			addq.b #1, d0
			rts
ntc_cmp_sle:
			cmp.w d1, d0
			sle d0
			addq.b #1, d0
			rts
ntc_cmp_sgt:
			cmp.w d1, d0
			sgt d0
			addq.b #1, d0
			rts
ntc_cmp_sge:
			cmp.w d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_cmp_ult:
			cmp.w d1, d0
			scs d0
			addq.b #1, d0
			rts
ntc_cmp_ule:
			cmp.w d1, d0
			sls d0
			addq.b #1, d0
			rts
ntc_cmp_ugt:
			cmp.w d1, d0
			shi d0
			addq.b #1, d0
			rts
ntc_cmp_uge:
			cmp.w d1, d0
			scc d0
			addq.b #1, d0
			rts
ntc_cmp_eq:
			cmp.w d1, d0
			rts
ntc_cmp_ne:
			cmp.w d1, d0
			sne d0
			addq.b #1, d0
			rts

			even
;## kw_scpltvl ntc_cmp
kw_scpltvl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_slt

			even
;## kw_scplevl ntc_cmp
kw_scplevl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_sle

			even
;## kw_scpgtvv ntc_cmp
kw_scpgtvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			bra ntc_cmp_sgt

			even
;## kw_scpgtvl ntc_cmp
kw_scpgtvl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_sgt

			even
;## kw_scpgevl ntc_cmp
kw_scpgevl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_sge

			even
;## kw_cpeqvv
kw_cpeqvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			cmp.w (a1), d0
			rts

			even
;## kw_cpeqvl
kw_cpeqvl:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			cmp.w (a0), d1
			rts

			even
;## kw_aget
;kw_aget, <arraybase>, <indexvar>, <destvar>
kw_aget:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			add.l d0, d0
			movea.l (sp)+, a1
			move.w 0(a0, d0.l), (a1)
			rts

			even
;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			add.l d0, d0
			movea.l (sp)+, a1
			move.w (a1), 0(a0, d0.l)
			rts

			even
;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
ntc_strcpy_lp:					; a0 -> a1, at most d1 chars (d1.w > 0), then the 0
			subq.w #1, d1
			bmi ntc_strcpy_cut
ntc_strcpy_l2:
			move.b (a0)+, (a1)+
			dbeq d1, ntc_strcpy_l2
			beq ntc_strcpy_e
ntc_strcpy_cut:
			clr.b (a1)
ntc_strcpy_e:
			rts

			even
;## kw_strcpyn kw_strcpy
;kw_strcpyn, <destaddr>, <srcaddr>, <capacity>  - into an array element (no capacity byte)
kw_strcpyn:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.l (sp)+, d1
			andi.w #$FF, d1
			bra ntc_strcpy_lp

			even
;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
kw_sc_end:
			tst.b (a1)
			beq kw_sc_copy
			addq.l #1, a1
			subq.w #1, d1
			bgt kw_sc_end
			rts
kw_sc_copy:
			tst.w d1
			beq kw_sc_none
			subq.w #1, d1
kw_sc_lp:
			move.b (a0)+, (a1)+
			dbeq d1, kw_sc_lp
			beq kw_sc_none
			clr.b (a1)
kw_sc_none:
			rts

			even
;## kw_strlen
;kw_strlen, <straddr>, <destvar>
kw_strlen:
			movea.l (sp)+, a0
			moveq #-1, d0
kw_sl_lp:
			addq.w #1, d0
			tst.b (a0)+
			bne kw_sl_lp
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
kw_seq_lp:
			move.b (a0)+, d0
			cmp.b (a1)+, d0
			bne kw_seq_no
			tst.b d0
			bne kw_seq_lp
kw_seq_no:
			rts

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			tst.b ntc_curx
			beq kw_pn0_end
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
kw_pn0_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## ntc_atoi ntc_data
; text at a0 to a number into the var at (ntc_ivar). Spaces first, then - , then
; digits (or &H hex). Then rts (the thread).
ntc_atoi:
			moveq #0, d0				; value
			moveq #0, d2				; minus
ntc_at_sp:
			move.b (a0), d1
			cmpi.b #' ', d1
			bne ntc_at_sg
			addq.l #1, a0
			bra ntc_at_sp
ntc_at_sg:
			cmpi.b #'-', d1
			bne ntc_at_amp
			moveq #1, d2
			addq.l #1, a0
			move.b (a0), d1
ntc_at_amp:
			cmpi.b #'&', d1
			bne ntc_at_dec
			addq.l #1, a0
			move.b (a0)+, d1
			ori.b #$20, d1
			cmpi.b #'h', d1
			bne ntc_at_done
ntc_at_hex:
			moveq #0, d1
			move.b (a0)+, d1
			subi.b #'0', d1
			bcs ntc_at_done
			cmpi.b #10, d1
			bcs ntc_at_hd
			ori.b #$20, d1
			subi.b #'a'-'0', d1
			bcs ntc_at_done
			cmpi.b #6, d1
			bcc ntc_at_done
			addi.b #10, d1
ntc_at_hd:
			lsl.w #4, d0
			or.w d1, d0
			bra ntc_at_hex
ntc_at_dec:
			moveq #0, d1
			move.b (a0)+, d1
			subi.b #'0', d1
			bcs ntc_at_done
			cmpi.b #10, d1
			bcc ntc_at_done
			mulu.w #10, d0
			add.w d1, d0
			bra ntc_at_dec
ntc_at_done:
			tst.w d2
			beq ntc_at_st
			neg.w d0
ntc_at_st:
			movea.l ntc_ivar, a0
			move.w d0, (a0)
			rts

			even
;## kw_cls ntc_data ntc_plat_screen
kw_cls:
			NTC_RS
			jsr ntc_plat_cls
			NTC_TS
			rts

			even
;## kw_ticks ntc_data ntc_plat_ticks
;kw_ticks, <destvar>  - the tick count (frames, 60 or 50 a second)
kw_ticks:
			movea.l (sp)+, a2
			NTC_RS
			jsr ntc_plat_ticks
			NTC_TS
			move.w d0, (a2)
			rts

; ============================================================
; String functions. Numbers are passed as the address of a word.
; Results go to a string buffer. Dest may be the same as the source.
; ============================================================

			even
;## ntc_getn
; a0 = address of a word: d0.w = its value limited to 0..255. jmp (a6). Keeps others.
ntc_getn:
			move.w (a0), d0
			bmi ntc_gn_zero
			cmpi.w #255, d0
			bls ntc_gn_ok
			move.w #255, d0
ntc_gn_ok:
			jmp (a6)
ntc_gn_zero:
			moveq #0, d0
			jmp (a6)

			even
;## kw_strleft ntc_getn
;kw_strleft, <dest>, <src>, <nvar>  - Left$(src, n)
kw_strleft:
			movea.l (sp)+, a1
			movea.l (sp)+, a2
			movea.l (sp)+, a0
			lea kw_sl_n, a6
			bra ntc_getn
kw_sl_n:
			movea.l a2, a0
; copy up to d0.w chars from a0 to a1, then the 0. rts (the thread)
ntc_strncpy:
			subq.w #1, d0
			bmi ntc_sn_end
ntc_sn_lp:
			move.b (a0)+, (a1)+
			dbeq d0, ntc_sn_lp
			beq ntc_sn_z
ntc_sn_end:
			clr.b (a1)
ntc_sn_z:
			rts

			even
;## kw_strright ntc_getn kw_strleft
;kw_strright, <dest>, <src>, <nvar>  - Right$(src, n)
kw_strright:
			movea.l (sp)+, a1
			movea.l (sp)+, a2
			movea.l (sp)+, a0
			lea kw_sr_n, a6
			bra ntc_getn
kw_sr_n:
			movea.l a2, a0
			moveq #-1, d1
kw_sr_len:
			addq.w #1, d1
			tst.b (a0)+
			bne kw_sr_len
			sub.w d0, d1				; len - n
			bpl kw_sr_skip
			moveq #0, d1
kw_sr_skip:
			lea 0(a2, d1.w), a0
			move.w #255, d0
			bra ntc_strncpy

			even
;## kw_strmid ntc_getn kw_strleft
;kw_strmid, <dest>, <src>, <startvar>, <lenvar>  - Mid$(src, start, len)
kw_strmid:
			movea.l (sp)+, a1
			movea.l (sp)+, a2
			movea.l (sp)+, a0
			lea kw_sm_s, a6
			bra ntc_getn
kw_sm_s:
			tst.w d0
			beq kw_sm_s1
			subq.w #1, d0
kw_sm_s1:
			tst.w d0
			beq kw_sm_len
			tst.b (a2)
			beq kw_sm_len
			addq.l #1, a2
			subq.w #1, d0
			bra kw_sm_s1
kw_sm_len:
			movea.l (sp)+, a0
			lea kw_sm_n, a6
			bra ntc_getn
kw_sm_n:
			movea.l a2, a0
			bra ntc_strncpy

			even
;## kw_strcstr ntc_itoa
;kw_strcstr, <dest>, <nvar>  - number to text (CStr, "x" & n)
kw_strcstr:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_next, a6
			bra ntc_itoa

			even
;## kw_strhex
;kw_strhex, <dest>, <nvar>  - Hex$(n), no leading zeros
kw_strhex:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.w (a0), d0
			moveq #3, d1				; 4 digits
			moveq #0, d3				; seen
kw_hx_lp:
			rol.w #4, d0
			move.w d0, d2
			andi.w #$F, d2
			bne kw_hx_out
			tst.w d3
			bne kw_hx_out
			tst.w d1
			bne kw_hx_next
kw_hx_out:
			moveq #1, d3
			addi.b #'0', d2
			cmpi.b #'9'+1, d2
			bcs kw_hx_put
			addq.b #7, d2
kw_hx_put:
			move.b d2, (a1)+
kw_hx_next:
			dbra d1, kw_hx_lp
			clr.b (a1)
			rts

			even
;## kw_strspace ntc_getn
;kw_strspace, <dest>, <nvar>  - Space$(n)
kw_strspace:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			lea kw_sps_n, a6
			bra ntc_getn
kw_sps_n:
			moveq #' ', d1
; d0.w = count (NTC_STRMAX at most), d1.b = char, a1 = dest. rts
ntc_strfill:
			cmpi.w #NTC_STRMAX, d0
			bls ntc_sf_ok
			move.w #NTC_STRMAX, d0
ntc_sf_ok:
			subq.w #1, d0
			bmi ntc_sf_end
ntc_sf_lp:
			move.b d1, (a1)+
			dbra d0, ntc_sf_lp
ntc_sf_end:
			clr.b (a1)
			rts

			even
;## kw_strstring kw_strspace
;kw_strstring, <dest>, <nvar>, <charvar>  - String$(n, char code)
kw_strstring:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			lea kw_ss_n, a6
			bra ntc_getn
kw_ss_n:
			movea.l (sp)+, a0
			move.b 1(a0), d1
			bra ntc_strfill

			even
;## kw_strucase
;kw_strucase, <dest>, <src>  - UCase$
kw_strucase:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
kw_uc_lp:
			move.b (a0)+, d0
			cmpi.b #'a', d0
			bcs kw_uc_put
			cmpi.b #'z', d0
			bhi kw_uc_put
			subi.b #32, d0
kw_uc_put:
			move.b d0, (a1)+
			bne kw_uc_lp
			rts

			even
;## kw_strlcase
;kw_strlcase, <dest>, <src>  - LCase$
kw_strlcase:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
kw_lc_lp:
			move.b (a0)+, d0
			cmpi.b #'A', d0
			bcs kw_lc_put
			cmpi.b #'Z', d0
			bhi kw_lc_put
			addi.b #32, d0
kw_lc_put:
			move.b d0, (a1)+
			bne kw_lc_lp
			rts

			even
;## kw_strltrim kw_strleft
;kw_strltrim, <dest>, <src>  - LTrim$
kw_strltrim:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
kw_lt_skip:
			cmpi.b #' ', (a0)
			bne kw_lt_copy
			addq.l #1, a0
			bra kw_lt_skip
kw_lt_copy:
			move.w #255, d0
			bra ntc_strncpy

			even
;## kw_strrtrim
;kw_strrtrim, <dest>, <src>  - RTrim$
kw_strrtrim:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
ntc_rt_go:
			movea.l a1, a2				; the start
ntc_rt_copy:
			move.b (a0)+, (a1)+
			bne ntc_rt_copy
			subq.l #1, a1				; on the 0
ntc_rt_lp:
			cmpa.l a2, a1
			beq ntc_rt_e
			cmpi.b #' ', -1(a1)
			bne ntc_rt_e
			subq.l #1, a1
			clr.b (a1)
			bra ntc_rt_lp
ntc_rt_e:
			rts

			even
;## kw_strtrim kw_strrtrim
;kw_strtrim, <dest>, <src>  - Trim$
kw_strtrim:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
kw_tr_skip:
			cmpi.b #' ', (a0)
			bne ntc_rt_go
			addq.l #1, a0
			bra kw_tr_skip

			even
;## kw_strasc
;kw_strasc, <src>, <destvar>  - Asc(src), 0 if empty
kw_strasc:
			movea.l (sp)+, a0
			moveq #0, d0
			move.b (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_strval ntc_atoi
;kw_strval, <src>, <destvar>  - Val(src): decimal or &H hex
kw_strval:
			movea.l (sp)+, a0
			move.l (sp)+, ntc_ivar
			bra ntc_atoi

			even
;## kw_strinstr ntc_getn
;kw_strinstr, <startvar>, <s1>, <s2>, <destvar>  - InStr(start, s1, s2)
kw_strinstr:
			movea.l (sp)+, a0
			lea kw_in_s, a6
			bra ntc_getn
kw_in_s:
			tst.w d0
			bne kw_in_s1
			moveq #1, d0
kw_in_s1:
			movea.l (sp)+, a2			; s1
			movea.l (sp)+, a3			; s2
			move.w d0, d1
kw_in_adv:
			subq.w #1, d1
			beq kw_in_try
			tst.b (a2)+
			bne kw_in_adv
			bra kw_in_nf
kw_in_try:
			movea.l a2, a0
			movea.l a3, a1
kw_in_cmp:
			move.b (a1)+, d2
			beq kw_in_found
			cmp.b (a0)+, d2
			beq kw_in_cmp
			tst.b (a2)+
			beq kw_in_nf
			addq.w #1, d0
			bra kw_in_try
kw_in_nf:
			moveq #0, d0
kw_in_found:
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_strcmp
; a0 = a, a1 = b: compare, jmp (a6) with Z = equal, C = a < b (unsigned bytes)
ntc_strcmp:
			move.b (a0)+, d0
			cmp.b (a1)+, d0
			bne ntc_scm_e
			tst.b d0
			bne ntc_strcmp
ntc_scm_e:
			jmp (a6)

			even
;## kw_strcmplt ntc_strcmp
;kw_strcmplt, <a>, <b>  - Z if a < b
kw_strcmplt:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_sclt, a6
			bra ntc_strcmp
kw_sclt:
			scs d0
			addq.b #1, d0
			rts

			even
;## kw_strcmple ntc_strcmp
kw_strcmple:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_scle, a6
			bra ntc_strcmp
kw_scle:
			sls d0
			addq.b #1, d0
			rts

			even
;## kw_strcmpgt ntc_strcmp
kw_strcmpgt:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_scgt, a6
			bra ntc_strcmp
kw_scgt:
			shi d0
			addq.b #1, d0
			rts

			even
;## kw_sget
;kw_sget, <arraybase>, <indexvar>, <dest>, <element size>  - dest = array(index)
kw_sget:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			movea.l (sp)+, a1			; dest
			move.l (sp)+, d1			; size
			mulu.w d1, d0
			adda.l d0, a0
			subq.w #1, d1
kw_sg_lp:
			move.b (a0)+, (a1)+
			dbra d1, kw_sg_lp
			rts

			even
;## kw_sset kw_strcpy
;kw_sset, <arraybase>, <indexvar>, <src>, <element size>  - array(index) = src, cut at the element
kw_sset:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.w (a0), d0
			movea.l (sp)+, a0			; src
			move.l (sp)+, d1			; size
			andi.l #$FFFF, d1
			mulu.w d1, d0
			adda.l d0, a1
			subq.w #1, d1				; capacity
			bra ntc_strcpy_lp

; ============================================================
; Array parameters and dynamic arrays. A procedure gets the address of a
; 12 byte descriptor: dc.w base (RAM, 16 bits), lower bound 1, lower bound 2,
; count 1, count 2, element size.
; ============================================================

			even
;## kw_bssinit ntc_data ntc_plat_screen
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  the RAM variables (not in the ROM). Check they fit under the end of RAM, then clear them.
;  Too big: a message, the program stops.
kw_bssinit:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			andi.l #$FFFF, d0
			move.l a0, d1
			add.l d0, d1
			cmpi.l #$01000000, d1
			bhi kw_bs_big
			tst.l d0
			beq kw_bs_e
kw_bs_lp:
			clr.b (a0)+
			subq.l #1, d0
			bne kw_bs_lp
kw_bs_e:
			rts
kw_bs_big:
			NTC_RS
			lea kw_bs_txt, a2
kw_bs_pl:
			moveq #0, d0
			move.b (a2)+, d0
			beq kw_bs_stop
			jsr ntc_plat_putc
			bra kw_bs_pl
kw_bs_stop:
			jsr ntc_plat_newline
			jmp kw_stop
kw_bs_txt:	dc.b "Not enough memory for the arrays", 0
			even

			even
;## ntc_md_boot ntc_plat_data ntc_data ntc_md_vdp ntc_md_fontdata ntc_plat_screen
; ------------------------------------------------------------
; the start ($200): TMSS, the Z80 held, RAM cleared and the RAM block copied
; from the ROM, the VDP, the font, the pads, the PSG quiet; then user mode
; on the real stack and into ntc_start
; ------------------------------------------------------------
VDP_DATA	equ $C00000
VDP_CTRL	equ $C00004
PSG_PORT	equ $C00011
NTC_USTACK	equ $00FF7800			; the real stack's top
ntc_md_entry:
			move.w #$2700, sr
			move.b $A10001, d0
			andi.b #$0F, d0
			beq ntc_mb_notmss
			move.l #'SEGA', $A14000		; TMSS
ntc_mb_notmss:
			move.w #$0100, $A11100		; the Z80's bus ours
			move.w #$0000, $A11200		; and the Z80 held in reset
			lea $FF0000, a0				; RAM cleared (below the supervisor stack's last words: no)
			move.w #($8000/4)-1, d0
ntc_mb_clr:
			clr.l (a0)+
			dbra d0, ntc_mb_clr
			lea $FF8000, a0
			move.w #($8000/4)-1, d0
ntc_mb_clr2:
			clr.l (a0)+
			dbra d0, ntc_mb_clr2
			lea ntc_romend, a0			; the RAM block's first image, from the ROM
			lea ntc_ram, a1
			move.l #ntc_ramend-ntc_ram, d0
			beq ntc_mb_nodata
ntc_mb_cp:
			move.b (a0)+, (a1)+
			subq.l #1, d0
			bne ntc_mb_cp
ntc_mb_nodata:
			move.w VDP_CTRL, d0			; (the VDP's control state reset)
			lea ntc_md_vregs, a0
			moveq #ntc_md_vregs_n-1, d0
ntc_mb_reg:
			move.w (a0)+, VDP_CTRL
			dbra d0, ntc_mb_reg
			move.l #$40000000, VDP_CTRL	; VRAM 0: all clear
			move.w #$8000-1, d0
ntc_mb_vram:
			move.w #0, VDP_DATA
			dbra d0, ntc_mb_vram
			move.l #$C0000000, VDP_CTRL	; CRAM
			moveq #64-1, d0
ntc_mb_cram:
			move.w #0, VDP_DATA
			dbra d0, ntc_mb_cram
			move.l #$40000010, VDP_CTRL	; VSRAM
			moveq #40-1, d0
ntc_mb_vsram:
			move.w #0, VDP_DATA
			dbra d0, ntc_mb_vsram
			move.l #$C0020000, VDP_CTRL	; palette 0 colour 1: the text, white
			move.w #$0EEE, VDP_DATA
			; the font: tiles 32-126 at $0400, 1 bit a pixel -> colour 1
			move.l #$44000000, VDP_CTRL
			lea ntc_md_font, a0
			move.w #95*8-1, d1
ntc_mb_font:
			move.b (a0)+, d2
			moveq #0, d3
			moveq #8-1, d4
ntc_mb_fbit:
			lsl.l #4, d3
			add.b d2, d2
			bcc ntc_mb_f0
			addq.b #1, d3
ntc_mb_f0:
			dbra d4, ntc_mb_fbit
			move.l d3, VDP_DATA
			dbra d1, ntc_mb_font
			move.w #$8174, VDP_CTRL		; the display on, the frame interrupt on
			; the pads: TH an output, high
			move.b #$40, $A10009
			move.b #$40, $A1000B
			move.b #$40, $A10003
			move.b #$40, $A10005
			; the PSG quiet
			move.b #$9F, PSG_PORT
			move.b #$BF, PSG_PORT
			move.b #$DF, PSG_PORT
			move.b #$FF, PSG_PORT
			move.b #40, ntc_scols
			move.b #28, ntc_srows
			move.l #NTC_USTACK, a0
			move.l a0, usp
			move.w #$0000, sr			; user mode, the interrupts on: A7 is now the user stack
			jmp ntc_start

ntc_md_vregs:
			dc.w $8004					; 0: no line interrupt
			dc.w $8134					; 1: display off for now, frame interrupt, DMA, 28 rows
			dc.w $8230					; 2: plane A at $C000
			dc.w $8328					; 3: the window at $A000
			dc.w $8407					; 4: plane B at $E000
			dc.w $856C					; 5: sprites at $D800
			dc.w $8600
			dc.w $8700					; 7: the backdrop: palette 0 colour 0
			dc.w $8800
			dc.w $8900
			dc.w $8AFF					; 10: line interrupt every 256 lines
			dc.w $8B00					; 11: whole screen scrolling
			dc.w $8C81					; 12: H40, no interlace
			dc.w $8D3F					; 13: horizontal scroll at $FC00
			dc.w $8E00
			dc.w $8F02					; 15: VDP address step 2
			dc.w $9001					; 16: planes 64 x 32 cells
			dc.w $9100					; 17, 18: no window
			dc.w $9200
ntc_md_vregs_n	equ (*-ntc_md_vregs)/2

; ------------------------------------------------------------
; interrupts and exceptions (supervisor mode, the supervisor stack)
; ------------------------------------------------------------
; the frame: count it, read the pads (3 or 6 button, once a frame - a 6
; button pad's counter needs the gap between reads), run the frame hook
ntc_md_vint:
			movem.l d0-d4/a0-a1, -(sp)
			addq.w #1, ntc_ticks
			addq.w #1, ntc_vbl
			lea $A10003, a0
			bsr ntc_md_pad
			move.w d0, ntc_pad1
			lea $A10005, a0
			bsr ntc_md_pad
			move.w d0, ntc_pad2
			move.l ntc_vhook, d0
			beq ntc_vi_nohook
			movea.l d0, a0
			jsr (a0)					; (keeps every register but d0-d4 / a0-a1)
ntc_vi_nohook:
			movem.l (sp)+, d0-d4/a0-a1
ntc_md_rte:
			rte
ntc_md_hint:
			rte

; a0 = the port's data register: d0 = its buttons (1 = held)
ntc_md_pad:
			move.b #$40, (a0)
			nop
			nop
			move.b (a0), d1				; ?1CBRLDU
			move.b #$00, (a0)
			nop
			nop
			move.b (a0), d2				; ?0SA00DU (TH's 2nd step)
			move.b #$40, (a0)
			nop
			nop
			move.b #$00, (a0)			; (4th: ?0SA00DU again)
			nop
			nop
			move.b #$40, (a0)
			nop
			nop
			move.b #$00, (a0)			; 6th: a 6 button pad says so here
			nop
			nop
			move.b (a0), d3				; ?0SA0000 on a 6 button pad
			move.b #$40, (a0)
			nop
			nop
			move.b (a0), d4				; ?1CBMXYZ on a 6 button pad (7th)
			move.b #$00, (a0)			; (8th: back to the start)
			nop
			nop
			move.b #$40, (a0)
			not.b d1
			not.b d2
			moveq #0, d0
			move.b d1, d0
			andi.b #$3F, d0				; Up Down Left Right B C
			lsl.b #2, d2
			andi.b #$C0, d2				; A, Start
			or.b d2, d0
			andi.b #$0F, d3
			bne ntc_mp_3b
			not.b d4
			andi.w #$0F, d4				; Z Y X Mode
			moveq #0, d1
			btst #2, d4
			beq ntc_mp_nx
			bset #8, d1					; X
ntc_mp_nx:
			btst #1, d4
			beq ntc_mp_ny
			bset #9, d1					; Y
ntc_mp_ny:
			btst #0, d4
			beq ntc_mp_nz
			bset #10, d1				; Z
ntc_mp_nz:
			btst #3, d4
			beq ntc_mp_nm
			bset #11, d1				; Mode
ntc_mp_nm:
			or.w d1, d0
ntc_mp_3b:
			rts

; an exception: its number and the PC on the console, then stop
ntc_md_ex2:	moveq #2, d7
			bra ntc_md_exg
ntc_md_ex3:	moveq #3, d7
ntc_md_exg:
			move.l 10(sp), d6			; bus / address error: the PC is further in
			bra ntc_md_exshow
ntc_md_ex4:	moveq #4, d7
			bra ntc_md_exn
ntc_md_ex5:	moveq #5, d7
			bra ntc_md_exn
ntc_md_ex6:	moveq #6, d7
			bra ntc_md_exn
ntc_md_ex7:	moveq #7, d7
			bra ntc_md_exn
ntc_md_ex8:	moveq #8, d7
			bra ntc_md_exn
ntc_md_ex9:	moveq #9, d7
			bra ntc_md_exn
ntc_md_ex10: moveq #10, d7
			bra ntc_md_exn
ntc_md_ex11: moveq #11, d7
			bra ntc_md_exn
ntc_md_exx:	moveq #0, d7
ntc_md_exn:
			move.l 2(sp), d6
ntc_md_exshow:
			move.w #$2700, sr
			move.l usp, a5				; the thread position
			jsr ntc_plat_newline
			lea ntc_md_extxt, a2
			bsr ntc_md_exstr
			move.l d7, d5
			moveq #2, d4
			bsr ntc_md_exhex
			lea ntc_md_expc, a2
			bsr ntc_md_exstr
			move.l d6, d5
			moveq #6, d4
			bsr ntc_md_exhex
			lea ntc_md_exsp, a2
			bsr ntc_md_exstr
			move.l a5, d5
			moveq #6, d4
			bsr ntc_md_exhex
ntc_md_exstop:
			bra ntc_md_exstop
ntc_md_exstr:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_md_exse
			jsr ntc_plat_putc
			bra ntc_md_exstr
ntc_md_exse:
			rts
ntc_md_exhex:					; d5 = value, d4 = digits
			move.w d4, d3
			subq.w #1, d3
			lsl.w #2, d4
			ror.l d4, d5
ntc_md_exh1:
			rol.l #4, d5
			move.w d5, d0
			andi.w #$F, d0
			addi.b #'0', d0
			cmpi.b #'9'+1, d0
			bcs ntc_md_exh2
			addq.b #7, d0
ntc_md_exh2:
			jsr ntc_plat_putc
			dbra d3, ntc_md_exh1
			rts
ntc_md_extxt:	dc.b "68000 EXCEPTION ", 0
ntc_md_expc:	dc.b " PC ", 0
ntc_md_exsp:	dc.b " SP ", 0
			even

			even
;## ntc_md_vdp
; VDP helpers on the real stack (jsr): keep d2-d7 / a2-a6
; ntc_md_vaddr: d0.w = VRAM address -> VDP_CTRL set to write there
ntc_md_vaddr:
			move.l d1, -(sp)
			moveq #0, d1
			move.w d0, d1
			andi.w #$3FFF, d1
			ori.w #$4000, d1
			swap d1
			move.w d0, d1
			rol.w #2, d1
			andi.w #3, d1
			move.l d1, VDP_CTRL
			move.l (sp)+, d1
			rts

			even
;## ntc_plat_data

			even
;## ntc_plat_screen ntc_plat_data ntc_data ntc_md_vdp ntc_md_logs
; ntc_plat_putc - d0.b = character: on plane A at the cursor, move on, a new
; line after the last column. Real stack, keeps d2-d7 / a2-a6
ntc_plat_putc:
			movem.l d0-d2/a0, -(sp)
		ifd NTC_MDLOG
			bsr ntc_md_log
		endif
			moveq #0, d1
			move.b ntc_cury, d1
			mulu.w #40, d1
			moveq #0, d2
			move.b ntc_curx, d2
			add.w d2, d1
			lea ntc_shadow, a0
			move.b d0, 0(a0, d1.w)
			bsr ntc_md_cell			; d0 = char, the cursor's cell
			addq.b #1, ntc_curx
			move.b ntc_curx, d0
			cmp.b ntc_scols, d0
			bcs ntc_pc_nowrap
			move.b #1, ntc_wrapped
			movem.l (sp)+, d0-d2/a0
			bra ntc_nl_do
ntc_pc_nowrap:
			clr.b ntc_wrapped
			movem.l (sp)+, d0-d2/a0
			rts

; the cell at the cursor gets character d0 (VRAM: plane A, 64 cells a row)
ntc_md_cell:
			movem.l d0-d1, -(sp)
			moveq #0, d1
			move.b ntc_cury, d1
			lsl.w #6, d1
			moveq #0, d0
			move.b ntc_curx, d0
			add.w d0, d1
			add.w d1, d1
			addi.w #$C000, d1
			move.w d1, d0
			bsr ntc_md_vaddr
			movem.l (sp)+, d0-d1
			move.l d1, -(sp)
			moveq #0, d1
			move.b ntc_tattr, d1
			lsl.w #8, d1
			move.b d0, d1
			add.w ntc_tbase, d1
			move.w d1, VDP_DATA
			move.l (sp)+, d1
			rts

; ntc_plat_newline - column 0, next row (scrolls at the bottom); nothing straight after a wrap
ntc_plat_newline:
		ifd NTC_MDLOG
			move.l d0, -(sp)
			moveq #10, d0
			bsr ntc_md_log
			move.l (sp)+, d0
		endif
			tst.b ntc_wrapped
			beq ntc_nl_do
			clr.b ntc_wrapped
			rts
ntc_nl_do:
			clr.b ntc_curx
			addq.b #1, ntc_cury
			move.b ntc_cury, d0
			cmp.b ntc_srows, d0
			bcs ntc_nl_e
			subq.b #1, ntc_cury
			bra ntc_md_scroll
ntc_nl_e:
			rts

; the text up a row: the shadow moved up, the last row cleared, plane A redrawn
ntc_md_scroll:
			movem.l d0-d3/a0-a1, -(sp)
			lea ntc_shadow, a0
			lea 40(a0), a1
			move.w #40*27-1, d0
ntc_sc_mv:
			move.b (a1)+, (a0)+
			dbra d0, ntc_sc_mv
			moveq #40-1, d0
ntc_sc_cl:
			move.b #' ', (a0)+
			dbra d0, ntc_sc_cl
			bsr ntc_md_redraw
			movem.l (sp)+, d0-d3/a0-a1
			rts

; plane A from the shadow (28 rows of 40)
ntc_md_redraw:
			movem.l d0-d3/a0, -(sp)
			lea ntc_shadow, a0
			moveq #0, d2				; row
			moveq #0, d3
			move.b ntc_tattr, d3
			lsl.w #8, d3
ntc_rd_row:
			move.w d2, d0
			lsl.w #7, d0
			addi.w #$C000, d0
			bsr ntc_md_vaddr
			moveq #40-1, d1
ntc_rd_col:
			moveq #0, d0
			move.b (a0)+, d0
			bne ntc_rd_ch
			moveq #' ', d0
ntc_rd_ch:
			or.w d3, d0
			add.w ntc_tbase, d0
			move.w d0, VDP_DATA
			dbra d1, ntc_rd_col
			addq.w #1, d2
			cmpi.w #28, d2
			bcs ntc_rd_row
			movem.l (sp)+, d0-d3/a0
			rts

			even
;## ntc_plat_cls @unit ntc_plat_screen ntc_plat_data ntc_data
; ntc_plat_cls - clear the console, the cursor home
ntc_plat_cls:
			movem.l d0/a0, -(sp)
			lea ntc_shadow, a0
			move.w #40*28-1, d0
ntc_cls_lp:
			move.b #' ', (a0)+
			dbra d0, ntc_cls_lp
			clr.b ntc_curx
			clr.b ntc_cury
			clr.b ntc_wrapped
			bsr ntc_md_redraw
			movem.l (sp)+, d0/a0
			rts

			even
;## ntc_md_logs
		ifd NTC_MDLOG
; test builds (vasm -DNTC_MDLOG): what the console was given, at $FF0000 on (the
; harness reads it): characters, 10 for a new line. $FF6FFC: where the next goes
ntc_md_log:
			move.l a0, -(sp)
			movea.l $FF6FFC, a0
			cmpa.l #$FF0000, a0
			bcc ntc_lg_ok
			lea $FF0000, a0
ntc_lg_ok:
			cmpa.l #$FF6FF0, a0
			bcc ntc_lg_full
			move.b d0, (a0)+
			move.l a0, $FF6FFC
ntc_lg_full:
			movea.l (sp)+, a0
			rts
		endif

			even
;## ntc_plat_key ntc_data ntc_plat_data ntc_plat_frame
; ntc_plat_scankey - d0 = the code of a button newly pressed on pad 1, or 0
ntc_plat_scankey:
			movem.l d1-d2/a0, -(sp)
			move.w ntc_pad1, d1
			move.w ntc_padseen, d2
			move.w d1, ntc_padseen
			not.w d2
			and.w d2, d1				; the new ones
			moveq #0, d0
			lea ntc_md_keys, a0
			moveq #0, d2
ntc_sk_lp:
			btst d2, d1
			bne ntc_sk_got
			addq.w #1, d2
			cmpi.w #12, d2
			bcs ntc_sk_lp
			bra ntc_sk_e
ntc_sk_got:
			move.b 0(a0, d2.w), d0
ntc_sk_e:
			movem.l (sp)+, d1-d2/a0
			rts
ntc_md_keys:	dc.b $F0, $F1, $F2, $F3, 'B', 'C', 'A', 13, 'X', 'Y', 'Z', 27
			even

; ntc_plat_getkey - wait for a button: d0 = its code
ntc_plat_getkey:
			bsr ntc_plat_scankey
			tst.b d0
			bne ntc_gk_e
			bsr ntc_plat_frame
			bra ntc_plat_getkey
ntc_gk_e:
			rts

			even
;## ntc_plat_frame ntc_plat_data
; ntc_plat_frame - wait for the next frame interrupt (the start of the vertical blank)
ntc_plat_frame:
			move.l d0, -(sp)
			move.w ntc_vbl, d0
ntc_fr_lp:
			cmp.w ntc_vbl, d0
			beq ntc_fr_lp
			move.l (sp)+, d0
			rts

			even
;## ntc_plat_ticks ntc_plat_data
; ntc_plat_ticks - d0.w = frames since the start (60 a second, 50 on a PAL machine)
ntc_plat_ticks:
			move.w ntc_ticks, d0
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - before the program stops: nothing to give back on a Mega Drive
ntc_plat_exit:
			rts

			even
;## ntc_md_fontdata
